export type ChatTextMessageKey = DashboardTextMessageKey<typeof chatMessages>;
export type ChatPluralMessageKey = DashboardPluralMessageKey<typeof chatMessages>;

export const translateChatMessage = (
  locale: DashboardLocale,
  key: ChatTextMessageKey,
  variables?: DashboardMessageVariables,
): string => translateDashboardMessage(chatMessages, locale, key, variables);

export const translateChatPlural = (
  locale: DashboardLocale,
  key: ChatPluralMessageKey,
  count: number,
  variables?: DashboardMessageVariables,
): string => translateDashboardPlural(chatMessages, locale, key, count, variables);
